import axios from 'axios';

const API_KEYS = {
  newsapi: process.env.REACT_APP_NEWSAPI_KEY,
  nytimes: process.env.REACT_APP_NYTIMES_KEY,
  guardian: process.env.REACT_APP_GUARDIAN_KEY,
};

const fetchNews = async (query: string, source: string, date: string, category: string, author: string) => {
  let url = '';

  switch (source) {
    case 'newsapi':
      url = `https://newsapi.org/v2/everything?q=${query}&from=${date}&category=${category}&apiKey=${API_KEYS.newsapi}`;
      if (author) {
        url += `&author=${encodeURIComponent(author)}`; // ✅ Apply author filtering for NewsAPI
      }
      break;

    case 'nytimes':
      url = `https://api.nytimes.com/svc/search/v2/articlesearch.json?q=${query}&begin_date=${date.replace(/-/g, '')}&fq=news_desk:("${category}")&api-key=${API_KEYS.nytimes}`;
      if (author) {
        url += `&fq=byline:("${encodeURIComponent(author)}")`; // ✅ Apply author filtering for NYTimes
      }
      break;

    case 'guardian':
      url = `https://content.guardianapis.com/search?q=${query}&from-date=${date}&section=${category}&api-key=${API_KEYS.guardian}&show-fields=all`;
      // 🚨 The Guardian API does not support filtering by author directly
      break;
  }

  console.log(`Fetching news from: ${url}`); // ✅ Debugging API requests

  const response = await axios.get(url);
  return response.data;
};

export { fetchNews };
